#ifndef XLANG_RUNTIME_PIPELINE_ABI_FROM_X
int xlang_asm_out_buf_is_object_magic(const unsigned char *data) {
    unsigned char b0;
    unsigned char b1;
    unsigned char b2;
    unsigned char b3;
    if (data == NULL) {
        return 0;
    }
    b0 = data[0];
    b1 = data[1];
    b2 = data[2];
    b3 = data[3];
    /* MH_MAGIC_64 LE */
    if (b0 == 0xcf) {
        if (b1 == 0xfa) {
            if (b2 == 0xed) {
                if (b3 == 0xfe) {
                    return 1;
                }
            }
        }
    }
    /* MH_CIGAM_64 */
    if (b0 == 0xfe) {
        if (b1 == 0xed) {
            if (b2 == 0xfa) {
                if (b3 == 0xcf) {
                    return 1;
                }
            }
        }
    }
    /* ELF */
    if (b0 == 0x7f) {
        if (b1 == 'E') {
            if (b2 == 'L') {
                if (b3 == 'F') {
                    return 1;
                }
            }
        }
    }
    return 0;
}
#endif /* XLANG_RUNTIME_PIPELINE_ABI_FROM_X */

