  if (cont_len_out)
    *cont_len_out = 0;
  if (!ctx || (s = wave114_loop_sc_find(ctx, 0)) < 0 || wave114_loop_depth[s] <= 0)
    return;
  wave114_loop_depth[s]--;
  d = wave114_loop_depth[s];
  if (d <= 0)
    return;
