  base = prev * WAVE114_LOOP_LABEL_W;
  sc_base = s * WAVE114_LOOP_STACK;
  bl = wave114_loop_break_lens[s * WAVE114_LOOP_DEPTH_MAX + prev];
  cl = wave114_loop_cont_lens[s * WAVE114_LOOP_DEPTH_MAX + prev];
