      if (var_off < 0)
        return -1;
      mod = pipeline_asm_emit_module_ref_c();
      field_off = glue_field_access_effective_offset_c(arena, mod, left_ref);
      load_sz = pipeline_expr_field_access_load_byte_sz(arena, mod, left_ref);
