#ifndef GLUE_TYPE_KIND_ARRAY
#define GLUE_TYPE_KIND_ARRAY 10
#endif
#ifndef GLUE_TYPE_KIND_SLICE
#define GLUE_TYPE_KIND_SLICE 11
#endif
