  blk_inner = glue_expr_block_transparent_value_ref_at(arena, expr_ref);
  if (blk_inner > 0)
    return glue_try_binop_load_operand_elf_c(arena, elf_ctx, blk_inner, ctx, ta, to_rbx);
  ko = pipeline_expr_kind_ord_at(arena, expr_ref);
