  if (!m || func_index < 0 || func_index >= ((W280_ModuleHdr *)m)->num_funcs || param_index < 0)
    return 0;
  pe = module_func_param_entry(m, func_index, param_index, 0);
  return pe ? (int32_t)pe->type_ref : 0;
