  int32_t *pt;
  int32_t n;
  int32_t k;
  if (!out || !(sc = (W281_OneFuncSc *)onefunc_sidecar_get(out, 1)) || !name || name_len <= 0 || name_len > 127)
    return -1;
  if (grow_vec_push(&sc->param_names) < 0 || grow_vec_push(&sc->param_name_lens) < 0 ||
      grow_vec_push(&sc->param_type_refs) < 0)
    return -1;
