int32_t pipeline_asm_user_deps_need_coemit(char **dep_paths, int32_t n) {
  int32_t i;
  if (!dep_paths || n <= 0)
    return 0;
  for (i = 0; i < n; i++) {
    uint8_t *p = (uint8_t *)(dep_paths[i] ? dep_paths[i] : "");
    if (memcmp(p, "std.", 4) == 0 || memcmp(p, "core.", 5) == 0)
      continue;
    return 1;
  }
  return 0;
}

