int32_t pipeline_copy_lib_root_to_buf256(struct ast_PipelineDepCtx *ctx, int32_t lib_idx, uint8_t *dst) {
  int32_t i;
  int32_t lr_len;
  if (!dst)
    return 0;
  for (i = 0; i < 256; i++)
    dst[i] = 0;
  if (!ctx || lib_idx < 0)
    return 0;
  lr_len = pipeline_ctx_lib_root_len(ctx, lib_idx);
  if (lr_len > 0)
    pipeline_ctx_lib_root_copy(ctx, lib_idx, dst, 256);
  return lr_len;
}

